class Solution {
  public int digitsCount(int d, int low, int high) {
    return (int) (count(d, high) - count(d, low - 1));
  }

  // occurrences of digit d in 1..n, position by position
  private long count(int d, long n) {
    long total = 0;
    for (long place = 1; place <= n; place *= 10) {
      long high = n / (place * 10), cur = n / place % 10, low = n % place;
      if (d == 0) high--; // zero cannot lead, so the highest block has no zero here
      if (cur > d) total += (high + 1) * place;
      else if (cur == d) total += high * place + low + 1;
      else total += high * place;
    }
    return total;
  }
}
